## `ringbuf.c`

```c
/*
 * ringbuf.c — Implementation details
 *
 * Interrupt-safety relies on:
 *   1. volatile on head/tail  → compiler must re-read from memory.
 *   2. Compiler memory barrier → prevents load/store reordering.
 *   3. Single-word stores     → atomic on all mainstream 32-bit+ CPUs
 *                              (x86, ARM Cortex-M, RISC-V, …).
 *   4. Power-of-2 size        → no division in the hot path.
 */

#include "ringbuf.h"

/* Compiler memory barrier (GCC / Clang / GCC-compatible). */
#define MEM_BARRIER()  __asm__ volatile("" ::: "memory")

/* ─── Init ───────────────────────────────────────────────────────── */

void ringbuf_init(ringbuf_t *rb, uint8_t *buf, uint32_t size)
{
    /* size must be a power of two */
    if (size == 0 || (size & (size - 1)) != 0)
        return;   /* invalid — caller should assert */

    rb->buf  = buf;
    rb->size = size;
    rb->mask = size - 1;
    rb->head = 0;
    rb->tail = 0;
}

/* ─── Produce (ISR-safe) ─────────────────────────────────────────── */

int ringbuf_produce(ringbuf_t *rb, uint8_t byte)
{
    uint32_t head = rb->head;          /* read own index (single writer) */
    uint32_t tail = rb->tail;          /* read consumer index             */

    if (head - tail >= rb->size)
        return -1;                     /* full */

    /* Write data BEFORE advancing head (consumer must see data first). */
    rb->buf[head & rb->mask] = byte;

    MEM_BARRIER();                     /* prevent compiler from sinking
                                          the head store before buf store */

    rb->head = head + 1;              /* single-word store → atomic */

    return 0;
}

/* ─── Consume ────────────────────────────────────────────────────── */

int ringbuf_consume(ringbuf_t *rb)
{
    uint32_t tail = rb->tail;          /* read own index (single reader) */
    uint32_t head = rb->head;          /* read producer index            */

    if (head == tail)
        return -1;                     /* empty */

    uint8_t byte = rb->buf[tail & rb->mask];

    MEM_BARRIER();                     /* prevent compiler from advancing
                                          tail before buf load completes */

    rb->tail = tail + 1;              /* single-word store → atomic */

    return (int)byte;
}
```

