## `example.c` — ISR Producer / Main Consumer

```c
/*
 * example.c — 16-byte UART-style ring buffer
 *
 * Compile (ARM Cortex-M example):
 *   arm-none-eabi-gcc -O2 -Wall -Wextra -mcpu=cortex-m4 \
 *       ringbuf.c example.c -o example
 *
 * Compile (host / Linux, for unit-testing):
 *   gcc -O2 -Wall -Wextra ringbuf.c example.c -o example
 */

#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

/* ─── Buffer setup ───────────────────────────────────────────────── */

#define RING_SIZE  16u          /* MUST be 2^n */
static uint8_t  ring_storage[RING_SIZE];
static ringbuf_t rb;

/* ─── "ISR" producer (simulated) ─────────────────────────────────── */

/* In real code this would be:
 *   void USART1_IRQHandler(void) { ringbuf_produce(&rb, USART1->DR); }
 */
static void simulate_isr(void)
{
    const char msg[] = "Hello, ISR!\n";
    for (size_t i = 0; i < sizeof(msg) - 1; i++) {
        int rc = ringbuf_produce(&rb, (uint8_t)msg[i]);
        if (rc < 0) {
            /* buffer overflow — handle / discard */
            fprintf(stderr, "[ISR] overflow at byte %zu\n", i);
        }
    }
}

/* ─── Main (consumer) ────────────────────────────────────────────── */

int main(void)
{
    ringbuf_init(&rb, ring_storage, RING_SIZE);

    printf("Ring buffer capacity: %u bytes\n", rb.size);

    /* Simulate an interrupt firing */
    simulate_isr();

    /* Consume everything in the main loop */
    printf("Consumed: ");
    int c;
    while ((c = ringbuf_consume(&rb)) >= 0) {
        putchar(c);
    }
    printf("\n");

    /* Demo: overflow behaviour */
    printf("\n--- Overflow test (fill 16 bytes, try 17th) ---\n");
    for (int i = 0; i < 17; i++) {
        int rc = ringbuf_produce(&rb, (uint8_t)(i & 0xFF));
        printf("  produce[%2d] => %s\n", i, rc == 0 ? "OK" : "FULL");
    }
    printf("  count = %u\n", ringbuf_count(&rb));

    /* Drain */
    printf("Drained: ");
    while ((c = ringbuf_consume(&rb)) >= 0)
        printf("%02X ", (unsigned char)c);
    printf("\n");

    printf("empty? %s\n", ringbuf_is_empty(&rb) ? "yes" : "no");

    return 0;
}
```

